// 针对有限计划的无资源编辑、幂等边界、严格存档与未知预计；不代替完整Main验收。
#include "resident/domains/player_plan/plan_lifecycle.hpp"
#include "resident/domains/player_plan/plan_codec.hpp"
#include "resident/domains/player_plan/plan_views.hpp"
#include "resident/domains/player_plan/plan_binding.hpp"
