    auto read=[&](const ChildCareReliefState& st,const ReceiptDetails& value){return player_plan_child_care_relief_completion(store,st,"player",start.action_id,value,2);};auto good=read(state,receipt);require(good.ok&&good.value&&good.value->success&&good.value->original_birth_accepted_id=="birth:original","relief preserves original birth identity without releasing its hold");auto cold=receipt;auto* cold_completion=std::get<AdvanceDetails>(cold.data).completed_actions.find(start.action_id);cold_completion->completed.reset();cold_completion->success.reset();cold_completion->code.reset();require(read(state,cold).ok,"relief original JSON family-only completion valid");
    auto bad=receipt;std::get<AdvanceDetails>(bad.data).completed_actions.find(start.action_id)->family->fact_id="family_care_relief:99";require(!read(state,bad).ok,"relief mismatched result rejected");bad=receipt;std::get<AdvanceDetails>(bad.data).completed_actions.find(start.action_id)->family->actor_id="other";require(!read(state,bad).ok,"relief provider exact");bad=receipt;std::get<AdvanceDetails>(bad.data).completed_actions.find(start.action_id)->success=false;require(!read(state,bad).ok,"actual feeding cannot become stopped");bad=receipt;std::get<AdvanceDetails>(bad.data).completed_actions.find(start.action_id)->military=MilitaryEffect{};require(!read(state,bad).ok,"relief rejects mixed military completion");
