    closure.reason="provider_dead";closure.cause_fact_id="military:4";completion.success=false;completion.code="RecoveryProviderDied";completion.growth.reset();AdvanceDetails death;death.completed_actions.insert(action,completion);good=read({death,{}});require(good.ok&&good.value&&!good.value->success&&good.value->code=="RecoveryProviderDied","explicit failed Advance binds original provider death");require(!read(cancel).ok,"cancel cannot pretend to be death");auto mixed_death=death;GrowthEffect hidden;hidden.kind="service";hidden.success=false;mixed_death.completed_actions.find(action)->growth=hidden;require(!read({mixed_death,{}}).ok,"death cannot hide code under legacy nested service JSON");recovery.closures.erase(closed);require(!read({death,{}}).ok,"missing closure never means arrival or successful recovery");
