void projections(){auto store=common();PlayerPlanState state;require(edit_player_plan(store,state,"player",move()).ok,"projection first");PlayerPlanAppend rest;rest.data=PlayerPlanRest{"estate",4};rest.source={PlayerPlanSourceKind::own_estate,"estate",0};require(edit_player_plan(store,state,"player",rest).ok,"projection rest");PlayerPlanAppend reminder;reminder.data=PlayerPlanTaskReminder{"task","gate"};reminder.source={PlayerPlanSourceKind::accepted_task,"task",0};require(edit_player_plan(store,state,"player",reminder).ok,"projection task");PlayerKnownCommitment task;task.ref={PlayerCommitmentKind::task,"task"};task.due_tick=3;auto projection=project_player_plan(state,0,{task},[](const auto& step){if(std::holds_alternative<PlayerPlanMove>(step.data))return PlayerPlanEstimate{0,"local_move",{}};if(std::holds_alternative<PlayerPlanRest>(step.data))return PlayerPlanEstimate{4,"own_rest",{}};return PlayerPlanEstimate{{},"task_owner","ManualCompletionUnknown"};});require(projection.ok,"project finite steps");require(projection.value.conflicts.size()==1&&projection.value.conflicts[0].known_conflict&&projection.value.conflicts[0].estimated_completion_tick==4,"deadline uses finish time");require(!projection.value.steps.back().completion_tick,"reminder not fulfillment");auto unknown=project_player_plan(state,0,{task},[](const auto&){return PlayerPlanEstimate{{},{},"unknown"};});require(unknown.ok&&!unknown.value.steps[1].start_tick&&unknown.value.conflicts[0].unknown,"unknown propagates without zero");auto overflow=project_player_plan(state,std::numeric_limits<Integer>::max(),{},[](const auto&){return PlayerPlanEstimate{1,"known",{}};});require(!overflow.ok,"estimate overflow rejected");auto view=encode_player_plan_view(state,projection.value);require(view.find("steps")->as<BoundaryValue::Array>()->size()==3,"finite view rows");}
