void commitments(){auto store=common();TaskState tasks;TaskCatalog catalog;CommonCatalog shared;GrowthState growth;TaskDefinition definition;definition.id="offer";definition.report_role="clerk";definition.display_name="已接托付";catalog.offers.insert("offer",definition);RoleDefinition role;role.id="clerk";role.place_id="office";shared.roles.insert(role.id,role);TaskRecord accepted;accepted.id="accepted";accepted.offer_id="offer";accepted.assignee="player";accepted.status="active";accepted.deadline_tick=6;tasks.tasks.insert(accepted.id,accepted);auto pending=accepted;pending.id="pending";pending.status="accepting";tasks.tasks.insert(pending.id,pending);auto other=accepted;other.id="other";other.assignee="npc";tasks.tasks.insert(other.id,other);StudyFact course;course.actor_id="player";course.terms.skill_id="rites";course.terms.context.place_id="school";growth.facts.insert("course",course);ActionCoreView action;action.id="course";action.kind="study_skill";action.actor_id="player";action.remaining_ticks=3;store.state().actions.insert(action.id,action);auto known=known_player_commitments(store,tasks,catalog,shared,growth,"player");require(known.ok&&known.value.size()==2,"only accepted own task and actual course");require(known.value[0].due_tick==6&&known.value[0].place_id=="office","original task deadline and report place");require(!known.value[1].due_tick&&known.value[1].estimated_completion_tick==3,"course estimate is not deadline");ContractRecord contract;contract.id="contract";contract.frozen_terms.deadline_tick=7;tasks.contracts.insert(contract.id,contract);tasks.tasks.find("accepted")->contract_id=contract.id;require(!known_player_commitments(store,tasks,catalog,shared,growth,"player").ok,"contradictory original deadline rejected");}

